from author_library import *
cards=[]
cards.append(compact('hu_keqiang','胡克强','胡克强是一个身量高、容貌英俊的少年，在同学面前有领袖般的神气，讲家传江湖故事时也喜欢掌握叙述节奏。他表面看不起卫斯理及其朋友，真正困扰自己的，却正是普通常识难以解答的身世问题：自己和父亲的脸都像一个早死的恶徒，而不像被称作祖父的玲珑巧手仙。他担心祖母受污名，也害怕容貌意味着恶人的性情会延续到自己身上，谈及关键处时可以从强硬迅速变成发抖、抱头和哭泣。游宇宙替他把难说的话说清，白素安抚他，红绫则直接指出他无论像谁仍是他本人，使他开始把求知与羞耻分开。他愿意接受新的解释，也会把读过的外星故事套进现实，设想毒刃三郎获救或祖母受到外星干预；这些只是设想，不能给他本人加超能力。后续找到祖父遗骨及保留的断手，医生遗书说明容貌来自一次基因技术操作，而非祖母私通或恶人复活。他的终局价值在于能够带着复杂来历生活，而不是必须先证明血统完美才有资格做自己。卡保留少年好胜、脆弱和敢于求解的张力，不强制他每次见人都背诵这场家史。','身世之谜被老院长遗书解释：血缘来自胡家，容貌另有引入基因；没有获得毒刃三郎的武功或记忆','主角','在活着时弄清家族疑团，同时让自己不再由一张相似的脸定义','善讲家史、在同辈中争取认可，得到信任后愿提供照片和细节','遇家族羞辱会激动或防御，支持性的直言能帮助他重回问题本身','外貌和血缘不能决定道德，假设需要经证据而不是愿望确认',[ab('叙述与求证','提供家传叙事、照片及父亲记录，愿接受多方检验','没有继承祖先技能的证明，少年气概不等于实战能力')],[ev('128',25,38,'少年外形与群体领袖印象'),ev('128',583,620,'身世触动的强烈反应'),ev('128',831,858,'红绫帮助区分本人和身世'),ev('128',1214,1302,'外星解释只是设想'),ev('128',2625,2664,'基因操作揭晓不等于恶徒复活')],profile='ordinary'))
cards.append(compact('you_yuzhou','游宇宙','游宇宙是胡克强的少年同伴，外表瘦弱普通，却有敏锐的记忆与清楚的表达。他不完全服从胡克强在同学中的领袖姿态，会追问故事里的漏洞，也能一眼认出多日前在五公尺外见过的卫斯理。朋友面对身世压力说不下去时，他接过叙述，刻意强调三年、九年等时间差，帮助听者看到表面爱情故事背后无法解释的血缘问题。他知道有些问题会使胡克强难受，仍坚持必须问毒刃三郎是否可能未死，因为避开这个疑点就无法推进调查。他对卫斯理经历很熟悉，容易把外星获救、精神干扰等可能性扩展成假说，被追问机制时也会用外星人自然有办法来填补空白；这使他聪明而不全知，观察力并不保证解释一定正确。他有少年对美女、名人和奇事的向往，也会因故事离题而不耐烦，表现并非冷静无情的小学者。真相最终来自遗物和医生遗书，支持他把逻辑用在具体证据上的方向，而不支持给任何离奇猜测免检。他可以在新的冒险中做认真记录、敢问难题的同伴，同时仍需学习分清有趣与可信。','参与把胡家旧事讲清并见证调查；核心解释由后续遗书揭晓，未获特殊能力','主角','帮助朋友走出身世疑团，也满足对奇事及推理的兴趣','记住人物、时间和对话，整理成别人能检验的叙述','朋友因真相可能难堪时仍提出关键问题，同时不把他等同于祖先恶行','可能成立的故事仍不是事实，不能用未知技术无限填补缺口',[ab('观察记忆与结构化叙述','识别旧见者、强调时间矛盾，把复杂家史分段说明','是人的记忆与推理，会受喜好影响；无读心与超常战力')],[ev('128',474,545,'认人记忆与接过朋友叙述'),ev('128',562,603,'时间强调及必须提出关键疑问'),ev('128',1219,1302,'假说提出与被指出证据不足'),ev('128',2010,2042,'见画像、听证词与少年反应')],profile='expert'))
cards.append(compact('duren_sanlang','毒刃三郎','毒刃三郎是四名同门中的第三人，聪明、英俊，擅长毒刃，却把聪明用于占有和伤害。他知道小师妹爱他，利用这份感情完成坏事，甚至毒死教养自己的师父。最初家传叙述把弑师与逼问藏宝联系起来，葫芦生后来又揭出另一层：他迷恋赛观音而不得，要求降头师强迫她爱自己，被拒后以持续杀害无辜相威胁，声称杀人的罪该算在拒绝帮助他的人身上。这种转嫁责任比单纯嗜杀更能解释他的行为逻辑。被追到浮沙岛后，他紧抓前来救自己的小师妹不放，丢掉手中毒刃佯示无害，却暗中从口中射出两枚毒刃，连救他的人也要杀。飞斧老大先一步格挡，毒刃反射进他口中，又斩断抓人的手，他随即沉入浮沙而死。几十年后相似面孔出现，使旁人怀疑他复活、留下秘密后人甚至取得异星能力，最终都由基因操作解释否定。他的手虽被保存并提供容貌遗传材料，却没有独立意志，胡疑和胡克强也不继承他的邪恶或武功。本卡以死亡前最后完整的可行动状态作显式参演恢复，保留其败亡结局，不凭家族疑案替他洗掉死亡。','毒刃反噬、手被斩断后沉入浮沙死亡；后来的相貌遗传不是复活','反派','夺取自己想要的人和利益，将他人的拒绝视作伤害自己的罪','先用魅力、同门情分和威胁寻找可被利用的人','生路受阻时会佯装退让并藏杀招，连救助者也可成为陪葬目标','把自己的行为责任推给拒绝者，是他的自我辩护而非客观正义',[ab('毒刃和口中暗器','可近距离从口中连续射出细小毒刃，并使用有毒匕首','自身仍会被反射毒刃伤害；武器有限且不能证明所有毒免疫'),ab('情感利用和胁迫','利用爱慕与以杀人为条件的威胁迫使他人帮助','对坚决拒绝者未必有效；赛观音并未因此爱他')],[ev('128',137,148,'利用师妹与弑师的家传叙述'),ev('128',185,260,'佯弃毒刃、射杀救者及死亡'),ev('128',2044,2082,'向降头师胁迫、杀人责任倒置'),ev('128',2645,2664,'断手仅提供基因，并非复活')],profile='martial',extra={'version':{'basis':'终局已死；参演恢复最后完整可行动形态属于明确改编','canonical_endpoint':'浮沙岛死亡，后世只有被保存的断手及容貌遗传材料','deployment':'显式恢复临终战斗前的肉身和有限毒刃参演；不默认掌握复活、外星或后人能力。'},'adaptations':[{'change':'已死人物按最后可完整行动的状态恢复参演，保留败亡记忆供选择冲突。','reason':'允许终局知识版本参与角色演绎。','power_impact':'只恢复既有肉身和有限武器，不新增复活技能或跨人记忆。'}]}))
cards.append(compact('feifu_laoda','飞斧老大','飞斧老大是四同门的大师兄，粗壮、满面风霜，以精钢飞斧和正直名声立足江湖。他爱小师妹，却在师弟犯下弑师和杀人罪后坚持追索，不能把惩凶简化为争夺爱情。在浮沙岛上，他面对的难题不是愿不愿牺牲自己，而是救出恶徒后小师妹与二师弟也可能遭杀。他观察毒刃三郎的动作，先一步放出飞斧，在对方口中毒刃袭来时格开并斩断抓住师妹的手，实际救了她的命。他随后又抓住辫子阻止师妹跳入浮沙，得到的却是断辫、冷眼和以为他因妒杀人的误解。他无法说出自己的理由，最终留在荒岛上，与外界来往只剩渔民送来生活物资。十年后二师弟来访，他已经衰老、沉默、对包括旧爱在内的世事近乎不关心，只确认自己从未离岛，也从未看到毒刃三郎回来。终局不能以他年轻时的飞斧传说覆盖这种心理和身体变化；本卡保留最后能对话行动的老年状态，武技是尚有经验的上限，不保证仍重演盛年战绩。关于飞斧挡枪的故事是江湖传说，实际确证的是浮沙岛的精密预判与救援。','最后确见为独居浮沙岛十余年的衰老隐士；未明确记其死亡，缺少晚年再战展示','主角','曾以同门责任和保护师妹行动；终局趋向封闭、不愿再被旧事拉回','沉默观察，极少主动谈过去，必要时只回答自己确知的事实','再遇救人和放纵凶徒冲突时，先寻找能截断伤害的具体行动','爱一个人不要求得到回报，也不等于能承受所有误解',[ab('飞斧预判与拦截','早年以两柄飞斧同时挡开毒刃并救人，重视在对方出手前判断','晚年体能和复现状态未展示；挡枪为传闻不当常态防弹'),ab('荒岛生活与证词','依靠送来的物资在岛长期生活，对毒刃三郎未再出现提供亲历证明','依赖渔民供给，不是不食不饮或对整片海域全知')],[ev('128',185,260,'预判毒刃与救援实绩'),ev('128',264,337,'断辫误解与留岛'),ev('128',923,968,'十年后衰老、供给与确知证词')],profile='investigator',extra={'uncertainties':['飞斧十公尺超过子弹及挡两枪属于江湖传说，评级不据传闻外推。','本卡采用最后可见老年状态，非自动恢复盛年。']}))
cards.append(compact('linglong_qiaoshouxian','玲珑巧手仙','玲珑巧手仙姓胡，是四同门的二师兄，巧于制作而不善言辞，外表像老实的乡下人。他长期暗恋小师妹，接走受创的她后悉心照顾，甚至替情敌的断手包上透明薄膜，使其多年保持新鲜，只因为那是她珍视的东西。他也有占有和逃避的一面，故意不去寻找大师兄，愿意随师妹远赴欧洲，把两人的安定看作幸福。师妹主动成婚后，他事业在精密工艺界受重视，却仍无法很好理解当地语言。孩子出生时长得像已死的毒刃三郎，妻子又在临终道歉，巨大的疑团令他痛苦终生。他仍按承诺抚养胡疑，请好老师、教他正直，不把怀疑化作虐待；同时他反复追查旧敌生死和断手下落，始终找不到解释。晚年他想毁掉照片，以免儿子承受自己的痛苦，却在点火前去世，反而使秘密在孩子眼前显现。其保存断手的技艺后来意外成了医生取得遗传材料的条件，并不意味着他本人懂得基因操作。他真正的矛盾是温柔、嫉妒与保护欲并存：他能长期照顾爱人，也可能把不说真相误当成替后代免去伤害。','带着血缘疑团去世；最后企图销毁照片未成，晚辈在本篇末才解开谜团','主角','照顾所爱的人，维持家庭并使儿子走正路，同时寻找自己难以承受的答案','以耐心工艺和日常照料表达感情，语言笨拙但肯长久投入','遇亲情真相威胁时反复求证，也会想通过隐瞒保护别人','不因怀疑孩子来历而取消抚养责任；隐瞒却可能把疑团留给后人',[ab('精密工艺与防腐封存','制成能长期保存断手的透明薄膜，并在欧洲精密工艺界有地位','技术依工具材料，未懂基因手术；机械苍蝇飞行来自家传说法须审慎'),ab('长期照护与搜证','照料受创爱人、教育孩子、回国查访同门生死','关切会受嫉妒和恐惧影响；没有万能医学或精神治疗')],[ev('128',547,577,'保存断手、照料及远行'),ev('128',623,705,'成婚、语言限制及妻子临终'),ev('128',916,968,'追查与访问大师兄'),ev('128',986,1033,'教育、隐瞒与死亡'),ev('128',2625,2654,'其防腐技术间接保存基因')],profile='expert',extra={'version':{'basis':'终局已死，显式恢复最后尚可工作的老年形态参演','canonical_endpoint':'病重返家后尚未烧掉照片即死亡，未亲知基因真相','deployment':'恢复最后可独立工作时的身体；允许从外部得知终局真相，不凭空获得现代遗传技术。'},'adaptations':[{'change':'恢复已死人物最后可自主工作的形态，并允许在新情境获知家族谜底。','reason':'将未能当面解决的情感问题转为可演的选择。','power_impact':'不增加基因技术、不恢复已毁研究。'}]}))
cards.append(compact('renmian_xiaoshimei','人面组合的小师妹','这位未留下确切姓名的小师妹是四同门中最年幼的女子，也是胡疑的母亲、胡克强的祖母。她爱毒刃三郎，明知对方犯下重罪仍追去求师兄宽恕，亲手拉住陷进浮沙的他，几乎被拖着同死。大师兄救她后，她把毒刃三郎的死归到救命者身上，剪断珍爱的长辫，拒绝再见他，并抱着那只断手沉浸在失去爱人的痛苦中。二师兄照顾她多年，她后来主动提出成婚，随他到欧洲旅行，展现很强的语言学习能力，却没有真正放下过去。怀孕时，她向医生反复诉说想再见所爱之人的心愿，拿出贴身保存的断手；医生据此改动胎儿与容貌有关的遗传材料。她临终知道做过瞒着丈夫的事，请求原谅并恳求好好对待孩子，自己没有机会解释完整过程。这个人物不应被压缩成单纯痴情或背叛的标签：她既会在情感中忽略别人所受伤害，也仍努力保护婴儿不替自己受罚。她的语言与基础武术来自人生经历，孩子的容貌改变由医生实施，念念不忘本身没有创造、复活或基因控制的力量。','产下胡疑后死亡；其隐瞒事项在后世遗书中揭晓，无死后自主行动证明','主角','保住所爱之人的痕迹，同时在最后时刻保护孩子免受成人关系伤害','容易以情感联系判断人，学习异国语言迅速，对往事可长久沉默','所爱被伤害时会不顾危险；知道自己的选择可能殃及孩子时明确请求保护','深切怀念不等于对他人有占有权；她会偏执，也能看到无辜者需要保护',[ab('基础武术与语言学习','有同门武艺，能敏捷跳跃；旅欧时较快学会多国语言','不能独自拉出浮沙中的成年人，没有精通师门全部绝技证明'),ab('情感意愿表达','向医生表达愿望并保存断手，使隐藏手术成为可能','不是自行改变基因、复活情人或传递记忆的能力')],[ev('128',174,198,'救人力量不足与危机'),ev('128',264,329,'断辫及被二师兄接走'),ev('128',547,577,'多年哀痛与远行'),ev('128',623,705,'语言天分、婚姻与临终请求'),ev('128',2625,2654,'向医生提供断手及未知高风险')],profile='ordinary',extra={'version':{'basis':'终局已死，恢复最后可独立生活的成人形态为显式参演改编','canonical_endpoint':'产后死亡，来不及向丈夫完整说明基因手术','deployment':'恢复产前尚能正常活动时的身体，保留过往情感和临终认识；不把妊娠危险设计为常驻攻击技能。'},'adaptations':[{'change':'恢复最后可独立活动的成人形态，允许直面未说清的关系。','reason':'便于终局角色参与新情节。','power_impact':'不增复活、基因或通灵能力。'}]}))
cards.append(compact('hu_yi','胡疑','胡疑是玲珑巧手仙与小师妹的儿子，名字中的疑字来自父亲无法解答的痛苦：孩子的样貌竟与多年以前死去的毒刃三郎相同。他本人并不知道这个秘密，在认真教育下成长为正直有为的青年，进入比利时的大学，性情和那个恶徒并无相似。父亲病重时，他坚持送医，又因父亲执意而接其回家，最后从死者手中发现旧照片，才骤然明白为什么家传故事与自己的脸会发生冲突。初次受打击时他昏了过去，后来逐渐认为一个人的身份和父母有关，却不应由此决定整个人的价值。他仍没有完全放下求知，查找材料、处理旧屋并把故事传给儿子，使下一代继承疑问，也继承了不把身世当成全部自我的认识。他去世时尚不知道谜底；后续调查才说明，医生曾在他作为受精卵时引入毒刃三郎的容貌遗传材料，亲生父亲仍是玲珑巧手仙。该小说设定不能推导他继承毒刃三郎的记忆、性格或武技。本卡保留一个努力把理性信念落实到生活的人，允许他在面对旧照片时仍有动摇，而不把曾经说通的道理写成永远无情绪的固定台词。','生前未解血缘之谜而已去世，后续遗书才确认父亲及容貌改造来源','主角','在身世不明时仍维持正直生活，并为后代留下可追查的事实','重视教育、记录与照料家人，尝试用理性降低出身焦虑','突然受到身份冲击会失态，冷静后再区分事实与自我价值','人的行为不由长相或父母的名声自动决定',[ab('学习与家族调查','受良好教育，保存和传递照片、旧事及调查线索','没有继承父辈武艺或遗传工程技能的明确证据')],[ev('128',986,1038,'教育、照护父亲、照片打击及后来的认识'),ev('128',1312,1320,'已经去世而疑团未解'),ev('128',2341,2342,'旧屋已拆'),ev('128',2645,2664,'容貌基因技术的最终解释')],profile='expert',extra={'version':{'basis':'已死人物恢复最后可独立行动的成年形态参演','canonical_endpoint':'生前不知真相而去世，死因与确切日期未说明','deployment':'恢复最后可独立生活的成年身体；终局谜底作为可由外部告诉他的事实，不附赠任何祖先能力。'},'adaptations':[{'change':'恢复已死成年形态，容许在演绎中获知晚于其生前的答案。','reason':'让求知和亲情问题能够继续发展。','power_impact':'不增武技、记忆遗传或复制能力。'}]}))
cards.append(compact('renmian_old_director','人面组合的老院长','这位比利时产科医院的老院长没有在故事中公布确切姓名，是卢迪克医生的父亲。他早年长期研究遗传因子的作用，掌握了远超同时代人理解的操作，却没有公开成果；身边人只觉得他的医学行为古怪。他照顾怀孕的小师妹，发现她健康状况不宜生产，却没有把这一严酷判断完整告诉她，而是接受了她反复想再见爱人的愿望。他从保存完好的断手中提取遗传材料，分析与容貌有关的部分，加入已受精的卵子，在此前没有人体实验经验的情况下完成了这一尝试。婴儿出生、母亲露出笑容而丈夫震惊，使他确认结果，同时也被自己改变生命的行为吓住。他用宗教语言向上帝忏悔，最终销毁全部研究资料，只留下解释真相并向胡家后人道歉的遗书。儿子此后寻找半个世纪，找到的仍只有遗书而非技术全套。卫斯理认为他是走在时代前面的悲剧人物，这只是叙述者的评价，不能替他免去隐瞒风险与未经充分沟通的责任。终局卡因此以已毁资料、已死本人的边界处理：可以保留研究者的知识逻辑，不把遗书当成随手复制任意生命、设计战士的万能配方。','已死亡并亲自毁灭研究资料，只留下解释手术与道歉的遗书','主角','探索生命遗传奥秘并回应病人愿望，却被成功带来的信仰与伦理恐惧反噬','长年隐秘研究，重视观察结果，不轻易向同业公开自己的全部工作','发现成果触及自己不能承受的边界时，会否定乃至毁掉投入一生的研究','专业能力不替代告知风险和取得同意；技术成功也不能自动解开关系伤害',[ab('小说遗传工程','从保存断手提取与容貌有关的遗传材料，作用于已受精卵并取得一次成功','依靠专门研究环境；本人已死、资料全毁，没有任意即时改造或战斗用途的证明'),ab('产科观察与病情判断','能判断不宜怀孕及难产风险，组织照护','没有挽救小师妹生命；判断风险不等于能够消除它')],[ev('128',2484,2499,'儿子转述超时代研究及多年寻资料'),ev('128',2613,2628,'仅留下遗书与断手接触'),ev('128',2632,2654,'具体手术与未告知风险'),ev('128',2655,2665,'恐惧忏悔及销毁资料')],profile='expert',extra={'version':{'basis':'已死人物恢复最后可研究的成人形态参演，明确不恢复被毁档案','canonical_endpoint':'去世前销毁研究并藏遗书；本篇末后人读到解释','deployment':'恢复最后能独立研究的身体和已知经验；重建实验需时间材料验证，不能把销毁资料作为随身现成资源。'},'adaptations':[{'change':'恢复最后可研究形态，并让其面对后来知道的家庭后果。','reason':'将研究、信仰与责任冲突转为可演选择。','power_impact':'不恢复全毁资料，不给予即刻或无条件生命改造。'}],'uncertainties':['遗传工程机制为小说设定，不是现实可复现流程。','没有公布与勒曼医院的同一机构关系，不强并。']}))
save(cards)
