def r(n,i,b,role='重要配角'):return(n,i,role,b)
cover('128',[r('卫斯理','wei_sili','听家史、分头搜证','主角'),r('白素','bai_su','按医院接触点查获遗书线索','主角'),r('红绫','hong_ling','帮助少年并调查医院'),r('温宝裕','wen_baoyu','讨论血缘及外星假说'),r('蓝丝','lan_si','请葫芦生协助'),r('白老大','bai_laoda','与葫芦生重见并拒重提旧情'),r('葫芦生','hu_lusheng','旧案证人、施血缘寻骨','主角'),r('赛观音','sai_guanyin','承诺与昔年关系关键人'),r('胡克强','hu_keqiang','求解自身家史','主角'),r('游宇宙','you_yuzhou','为朋友叙事与质疑','主角'),r('胡疑','hu_yi','家族第二代疑案主体','主角'),r('毒刃三郎','duren_sanlang','弑师杀人、胁迫、死亡','反派'),r('飞斧老大','feifu_laoda','惩凶救人与留岛','主角'),r('玲珑巧手仙','linglong_qiaoshouxian','保存断手、抚养与终生寻疑','主角'),r('小师妹','renmian_xiaoshimei','愿望与生育决定','主角'),r('老院长','renmian_old_director','实施基因操作及毁资料','主角')],[('卢迪克医生','一次继承资料调查的合作专家，主要解释父亲遗书，未见跨书重要行动'),('四同门师父','无姓名，主要为弑师受害背景，未展示足够独立行动'),('其他同学、电影明星','听众或仰慕对象，无符合范围的重要独立行动')],['将历史回述和现代调查分开；未知姓名者用描述名，不自行补实名。','基因改变不等于恶人复活、记忆或道德遗传。'])
